Translate("ruRU", "azeroth", {
	title = "Азерот",
	sections = {
		{
			title = "Обзор",
			text = [=[Азерот — это мир. Его моря омывают континенты: {link:eastern-kingdoms}Восточные королевства{/link}, {link:kalimdor}Калимдор{/link} и скованный льдом Нордскол, а кроме них — бесчисленные острова. Джунгли, пустыни, леса и ледяные поля лежат в нем бок о бок, и в каждой земле руины былых эпох покоятся под городами новой. Это мир многих народов и очень долгой памяти. Снова и снова его заставляли истекать кровью силы, которые желали им завладеть, и снова и снова он выстаивал.]=],
		},
		{
			title = "Истоки",
			text = [=[Древнейшие летописи говорят, что Азерот создали титаны — богоподобные существа, которые странствовали среди звезд и несли порядок в найденные ими миры. Когда они пришли в Азерот, им правили неистовые элементали и древнее зло, что впилось в этот мир. Летописи называют это зло Древними богами. Титаны сломили могущество и тех, и других. Повелителей стихий они заточили в царстве, отделенном от мира, а Древних богов заключили глубоко под землей, ибо их нельзя было убить, не ранив сам мир. Затем титаны придали земле облик. Их слуги воздвигли горы, прорезали долины и наполнили моря. Земельникам, существам из живого камня, было поручено заботиться о глубинах мира. Среди драконов титаны избрали пятерых и наделили каждого долей своей силы. Они стали Аспектами, которым надлежало хранить Азерот, когда его создатели уйдут. Потом титаны ушли, и мир был оставлен его собственным народам.]=],
		},
		{
			title = "Эпохи мира",
			text = [=[• {b}Империя Калдореи.{/b} В сердце единого великого континента лежал {link:well-of-eternity}Источник Вечности{/link}. На его берегах {link:night-elves}ночные эльфы{/link} воздвигли империю чудес, которой правила {link:queen-azshara}королева Азшара{/link}.
• {b}Война древних.{/b} Безрассудная магия высокорожденных привлекла взор {link:burning-legion}Пылающего Легиона{/link}. В {link:war-of-the-ancients}Войне древних{/link} ночные эльфы сражались за само существование мира, а уничтожение Источника вызвало {link:great-sundering}Великий Раскол{/link}. Единый континент был разбит на многие.
• {b}Младшие народы.{/b} В последующие эпохи империи троллей пришли в упадок, а под горами пробудились {link:dwarves}дворфы{/link}. {link:high-elves}Высшие эльфы{/link} основали {link:quel-thalas}Кель'Талас{/link}, а племена {link:humans}людей{/link} объединились в {link:arathor}Аратор{/link}, чтобы сражаться в {link:troll-wars}Войнах с троллями{/link}.
• {b}Эпоха Орды.{/b} Когда открылся {link:dark-portal}Темный портал{/link}, {link:orcs}орки{/link} из другого мира хлынули в Азерот. Последовали {link:first-war}Первая война{/link}, {link:second-war}Вторая война{/link} и {link:third-war}Третья война{/link}, и каждая была страшнее предыдущей.]=],
		},
		{
			title = "Общее имя",
			text = [=[Имя Азерот некогда принадлежало и одному королевству людей. Изгнанники из народа {link:arathi-highlands}Арати{/link}, которые поселились в южных лесах, назвали свою новую державу Азеротом, а ее столицей был {link:stormwind-city}Штормград{/link}. Со временем державу стали называть по имени ее города, и сегодня это {link:kingdom-of-stormwind}королевство Штормград{/link}. Старые солдаты {link:first-war}Первой войны{/link} до сих пор иногда говорят «Азерот» и имеют в виду лишь королевство, которое потеряли.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:third-war}Третья война{/link} окончилась тем, что {link:archimonde}Архимонд{/link} пал у подножия древа {link:nordrassil}Нордрассил{/link}, но мира она не принесла. {link:scourge}Плеть{/link} удерживает север {link:lordaeron}Лордерона{/link}. Слуги Пылающего Легиона все еще рыщут в лесах {link:kalimdor}Калимдор{/link}а. {link:alliance}Альянс{/link} и {link:horde}Орда{/link}, которые стояли вместе на горе Хиджал, теперь с подозрением следят друг за другом через {link:burning-steppes}Степи{/link} и чащи Ясеневого леса. Под Черной горой {link:dark-iron-dwarves}дворфы Черного Железа{/link} служат повелителю живого огня. Азерот пережил все войны, какие до сих пор велись на нем. Ни один летописец не осмелится сказать, что он не может пасть.]=],
		},
	},
})

Translate("ruRU", "eastern-kingdoms", {
	title = "Восточные королевства",
	sections = {
		{
			title = "Обзор",
			text = [=[Восточные королевства простираются от ледяных вершин {link:alterac-mountains}Альтерака{/link} до джунглей {link:stranglethorn-vale}Тернистой долины{/link}. Это родина {link:humans}людей{/link}, {link:dwarves}дворфов{/link} и {link:gnomes}гномов{/link}, а также {link:high-elves}высших эльфов{/link} {link:quel-thalas}Кель'Таласа{/link}. Здесь стояли великие королевства людей былых времен, и здесь {link:horde}Орда{/link} начала свою первую войну против {link:azeroth}Азерот{/link}а. Эти земли несут шрамы каждой войны, что была с тех пор. Некогда гордые державы лежат в руинах, а север стал землей мертвых.]=],
		},
		{
			title = "Истоки",
			text = [=[До {link:great-sundering}Великого Раскола{/link} эти земли были восточной окраиной единого континента. Когда {link:well-of-eternity}Источник Вечности{/link} был уничтожен, моря хлынули внутрь и оторвали их. То, что осталось, было землей уже древней. Титаны оставили здесь свои творения, и среди них — {link:uldaman}хранилище Ульдаман{/link} в каменистых {link:badlands}Бесплодных землях{/link}. В его залах спали их слуги, земельники. За долгие века земельники изменились. Их плоть стала мягкой, а жизнь — короткой, и от них произошли {link:dwarves}дворф{/link}ы Каз Модана. Другой народ, созданный титанами, как написано, дал начало {link:gnomes}гном{/link}ам. {link:trolls}Тролли{/link} жили в этих землях еще раньше. Племена Амани правили северными лесами, а Гурубаши владели южными джунглями.]=],
		},
		{
			title = "История",
			text = [=[• {b}Приход эльфов.{/b} Изгнанные из {link:kalimdor}Калимдора{/link}, высокорожденные пересекли море и основали {link:quel-thalas}Кель'Талас{/link} в северных лесах, на землях, которые тролли Амани считали своими.
• {b}Аратор.{/b} Племена людей севера объединил {link:thoradin}Торадин{/link}, который воздвиг город {link:stromgarde-keep}Стром{/link}. Вместе с эльфами его войска сокрушили троллей Амани в {link:troll-wars}Войнах с троллями{/link}. В награду эльфы обучили людей магии {link:arathor}Арати{/link}, а позже маги этой школы основали Даларан.
• {b}Семь королевств.{/b} Со временем Аратор распался. На севере поднялись королевства {link:lordaeron}Лордерон{/link}, {link:gilneas}Гилнеас{/link}, {link:kul-tiras}Кул Тирас{/link}, {link:alterac-mountains}Альтерак{/link}, {link:dalaran}Даларан{/link} и Стромгард. На юге изгнанники из народа {link:arathi-highlands}Арати{/link} основали державу, которая стала {link:kingdom-of-stormwind}королевством Штормград{/link}.
• {b}Три Молота.{/b} Под горами {link:dwarves}дворф{/link}ы {link:kingdom-of-ironforge}Стальгорна{/link} разделились на кланы: Бронзобородов, Неистового Молота и Черного Железа. Их война окончилась в огне. Тан-чародей клана Черного Железа, {link:ruins-of-thaurissan}Тауриссан{/link}, призвал повелителя огня {link:ragnar-thunderbrew}Рагнар{/link}оса, и этот призыв воздвиг Черную гору и выжег земли вокруг нее.
• {b}Войны Орды.{/b} На юге открылся {link:dark-portal}Темный портал{/link}. {link:stormwind-city}Штормград{/link} пал в {link:first-war}Первой войне{/link}. {link:alliance}Альянс{/link} Лордерона отбросил Орду во {link:second-war}Второй войне{/link}. Затем пришли чума нежити, {link:culling-of-stratholme}Очищение Стратхольма{/link} и {link:fall-of-lordaeron}падение Лордерона{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:stormwind-city}Штормград{/link} поднялся вновь, хотя его король пропал, а его регент, {link:bolvar-fordragon}Болвар Фордрагон{/link}, удерживает державу, силы которой растянуты до предела. В {link:ironforge}Стальгорн{/link}е правит {link:magni-bronzebeard}Магни Бронзобород{/link}; город дал приют и {link:gnomes}гном{/link}ам, ибо {link:gnomeregan}Гномреган{/link} погублен собственной бедой. К северу от Моста Тандола великого королевства {link:lordaeron}Лордерон{/link} больше нет. {link:scourge}Плеть{/link} удерживает Чумные земли. Фанатики {link:scarlet-crusade}Алого ордена{/link} сражаются с ней огнем и подозрением в равной мере. В руинах старой столицы {link:forsaken}Отрекшиеся{/link} устроили себе дом под землей. В Черной горе {link:dwarves}дворф{/link}ы Черного Железа и {link:orcs}орк{/link}и воюют друг с другом. А на юге, в {link:blasted-lands}Выжженных землях{/link}, безмолвно стоит {link:dark-portal}Темный портал{/link}.]=],
		},
	},
})

Translate("ruRU", "kalimdor", {
	title = "Калимдор",
	sections = {
		{
			title = "Обзор",
			text = [=[Калимдор лежит за морем, к западу от {link:eastern-kingdoms}Восточных королевств{/link}. Это земля старых лесов и красных каньонов, великих равнин и раскаленных пустынь. Это родина {link:night-elves}ночных эльфов{/link} и {link:tauren}тауренов{/link} и древнее сердце мира. Нынешний Калимдор — лишь то, что уцелело после {link:great-sundering}Великого Раскола{/link}. До этой катастрофы единый континент вмещал почти все земли {link:azeroth}Азерот{/link}а, а озером в его середине был {link:well-of-eternity}Источник Вечности{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[Древнейшими народами Калимдора были тролли, чьи империи широко раскинулись по первозданному континенту. Одно племя троллей, которое поселилось у Источника, за многие поколения изменилось под действием его силы. Они стали ночными эльфами и назвали эту землю Калимдором. У Источника они построили города империи Калдореи, которой правила {link:queen-azshara}королева Азшара{/link}. Их погоня за {link:arcane-magic}тайной магией{/link} привела в мир {link:burning-legion}Пылающий Легион{/link}. В {link:war-of-the-ancients}Войне древних{/link} Источник был уничтожен, а континент расколот. Моря хлынули в рану, и с тех пор там бурлит Водоворот. На склонах горы Хиджал уцелевшие посадили древо {link:nordrassil}Нордрассил{/link}, и десять тысяч лет ночные эльфы втайне несли стражу над своими лесами.]=],
		},
		{
			title = "История",
			text = [=[• {b}Долгое Бдение.{/b} {link:night-elves}Ночные эльфы{/link}, которых вели {link:malfurion-stormrage}Малфурион Ярость Бури{/link} и {link:tyrande-whisperwind}Тиранда Шелест Ветра{/link}, отреклись от тайной магии. Друиды спали в {link:emerald-dream}Изумрудном Сне{/link}, а {link:sentinels}Часовые{/link} одни охраняли леса.
• {b}Народы диких земель.{/b} По равнинам кочевали {link:tauren}таурен{/link}ы. Поколениями их теснили {link:centaurs}кентавры{/link} юга, {link:quilboar}свинобразы{/link} Степей, {link:harpies}гарпии{/link} скал и {link:furbolgs}фурболги{/link} лесов.
• {b}Третья война.{/b} В {link:third-war}Третьей войне{/link} море пересекла новая {link:horde}Орда{/link}, вождем которой был {link:thrall}Тралл{/link}, а с ней и люди, которых вела {link:jaina-proudmoore}Джайна Праудмур{/link}. {link:burning-legion}Пылающий Легион{/link} последовал за ними. {link:orcs}Орки{/link}, люди и ночные эльфы, прежде чужие друг другу и враги, встали вместе в {link:battle-of-mount-hyjal}битве у горы Хиджал{/link}, и там был уничтожен {link:archimonde}Архимонд{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[Калимдор больше не сокрытая земля. {link:night-elves}Ночные эльфы{/link} посадили новое древо, {link:teldrassil}Тельдрассил{/link}, и его город {link:darnassus}Дарнасс{/link} смотрит на северное море. {link:orcs}Орки{/link} основали {link:durotar}Дуротар{/link} и город {link:orgrimmar}Оргриммар{/link}, а {link:tauren}таурен{/link}ы, которых ведет {link:cairne-bloodhoof}Кэрн Кровавое Копыто{/link}, сделали своим домом {link:thunder-bluff}Громовой Утес{/link} в {link:mulgore}Мулгор{/link}е. {link:darkspear-trolls}Тролли Черного Копья{/link} живут рядом с орками. {link:jaina-proudmoore}Джайна Праудмур{/link} удерживает {link:theramore-isle}Терамор{/link} в {link:dustwallow-marsh}Пылевых топях{/link}. Но мир, заключенный на Хиджале, расползается по швам. Орки-лесорубы валят деревья Ясеневого леса, а {link:sentinels}Часовые{/link} отвечают стрелами. Гоблины {link:steamwheedle-cartel}картеля Хитрая Шестеренка{/link} и {link:venture-company}Торговой Компании{/link} торгуют и грабят вдоль побережий. Леса {link:felwood}Оскверненного леса{/link} все еще несут на себе порчу Легиона, а в пустынях юга спят тайны более древние.]=],
		},
	},
})

Translate("ruRU", "war-of-the-ancients", {
	title = "Война древних",
	sections = {
		{
			title = "Обзор",
			text = [=[Война древних была первым вторжением {link:burning-legion}Пылающего Легиона{/link} в {link:azeroth}Азерот{/link}. Она шла примерно за десять тысяч лет до того, как открылся {link:dark-portal}Темный портал{/link}, и положила конец империи Калдореи. Ее последний час принес {link:great-sundering}Великий Раскол{/link}, который разбил мир.]=],
		},
		{
			title = "Истоки",
			text = [=[Высокорожденные при дворе ночных эльфов все глубже черпали силу {link:well-of-eternity}Источника Вечности{/link}. Их магию почуял за пределами мира {link:sargeras}Саргерас{/link}, падший титан, который ведет {link:burning-legion}Пылающий Легион{/link}. Он стал шептать королеве, и она поверила ему. {link:queen-azshara}Королева Азшара{/link} и ее высокорожденные трудились над тем, чтобы открыть в Источнике врата, через которые Саргерас и его демоны могли бы войти в {link:azeroth}Азерот{/link}.]=],
		},
		{
			title = "История",
			text = [=[Первые демоны прошли через врата; их вели {link:archimonde}Архимонд{/link} и {link:mannoroth}Маннорот{/link}, и они истребляли ночных эльфов, которые вставали у них на пути. Против них и против королевы поднялось сопротивление. Его возглавил {link:malfurion-stormrage}Малфурион Ярость Бури{/link}, молодой ученик полубога Кенария, а вместе с ним — жрица {link:tyrande-whisperwind}Тиранда Шелест Ветра{/link} и его брат-близнец {link:illidan-stormrage}Иллидан Ярость Бури{/link}. К битве присоединились полубоги диких земель и стаи драконов. Война была почти проиграна, когда Хранитель Земли из числа драконов предал свой род. Это был Аспект, которому предстояло стать {link:deathwing}Смертокрылом{/link}. В конце концов защитники достигли дворца высокорожденных и разрушили их заклинания в тот миг, когда {link:sargeras}Саргерас{/link} пытался пройти через врата. Врата рухнули, и {link:well-of-eternity}Источник Вечности{/link} разорвал сам себя.]=],
		},
		{
			title = "Значение",
			text = [=[Война научила ночных эльфов тому, что тайная магия едва не погубила мир. Они отреклись от нее, обратились к друидизму и поклонению богине Элуне и начали свое долгое бдение. Она же сделала {link:illidan-stormrage}Иллидан{/link}а изменником в глазах своего народа: он втайне действовал заодно с высокорожденными, а после создал новый Источник на вершине горы Хиджал.]=],
		},
	},
})

Translate("ruRU", "great-sundering", {
	title = "Великий Раскол",
	aliases = { "Раскол" },
	sections = {
		{
			title = "Обзор",
			text = [=[Великий Раскол — катастрофа, которой завершилась {link:war-of-the-ancients}Война древних{/link}. Когда {link:well-of-eternity}Источник Вечности{/link} рухнул, единый континент древнего мира был расколот, и моря хлынули внутрь, чтобы заполнить рану. Лик {link:azeroth}Азерот{/link}а изменился навсегда.]=],
		},
		{
			title = "История",
			text = [=[Врата высокорожденных были разрушены в последний час войны. Источник, в который влили больше силы, чем он мог вместить, схлопнулся. Взрыв вырвал сердце континента. Большую часть империи Калдореи вместе с ее сияющей столицей Зин-Азшари поглотило море. {link:queen-azshara}Королева Азшара{/link} и многие ее высокорожденные были утянуты под волны. Там, где был Источник, воды начали вращаться, и родилась великая буря, которую называют Водоворотом. Она не утихает никогда.]=],
		},
		{
			title = "Мир после Раскола",
			text = [=[Над водой остались лишь осколки старого континента. Крупнейшие из них стали {link:kalimdor}Калимдором{/link} на западе и {link:eastern-kingdoms}Восточными королевствами{/link} на востоке, а ледяная земля Нордскол лежала на севере. Уцелевшие ночные эльфы собрались на склонах горы Хиджал. Там они узнали, что {link:illidan-stormrage}Иллидан Ярость Бури{/link} унес с собой сосуды с водой Источника и вылил их в горное озеро, создав второй Источник. Чтобы охранять его, Аспекты посадили над его водами древо {link:nordrassil}Нордрассил{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[Для ночных эльфов Раскол стал доказательством того, какова цена {link:arcane-magic}тайной магии{/link}. Для мира он означал десять тысяч лет разобщения. Народы востока и запада забыли друг о друге, пока {link:third-war}Третья война{/link} не свела их снова. Говорят, что {link:naga}наги{/link}, которые ныне рыщут у побережий, — это утонувшие высокорожденные, изменившиеся до неузнаваемости.]=],
		},
	},
})

Translate("ruRU", "troll-wars", {
	title = "Войны с троллями",
	sections = {
		{
			title = "Обзор",
			text = [=[Войны с троллями шли между троллями Амани и молодыми королевствами людей и {link:high-elves}высших эльфов{/link}, примерно за две тысячи восемьсот лет до того, как открылся {link:dark-portal}Темный портал{/link}. Из них родились союз эльфов и людей и первые маги-люди.]=],
		},
		{
			title = "Истоки",
			text = [=[Высокорожденные, изгнанные из {link:kalimdor}Калимдора{/link}, основали {link:quel-thalas}Кель'Талас{/link} в северных лесах {link:eastern-kingdoms}Восточных королевств{/link}. Эти леса принадлежали племенам Амани, и тролли не простили кражи. Тысячи лет они воевали с эльфами. {link:nak}Нак{/link}онец они собрали {link:ogres}огр{/link}омное войско, к которому, возможно, примкнули их сородичи Гурубаши, и выступили, чтобы уничтожить Кель'Талас до основания.]=],
		},
		{
			title = "История",
			text = [=[В ту же эпоху {link:thoradin}Торадин{/link} из племени {link:arathi-highlands}Арати{/link} объединил племена людей севера в державу {link:arathor}Аратор{/link} со столицей в городе {link:stromgarde-keep}Стром{/link}. Эльфы {link:quel-thalas}Кель'Талас{/link}а в отчаянии отправили к нему послов. Торадин согласился помочь им, если эльфы обучат его народ магии. Эльфы выбрали сто человек, у которых был дар к этому искусству, и научили их только тому, что было необходимо. Союзные войска встретили полчища Амани на юге {link:alterac-mountains}Альтерак{/link}ских гор. Маги-люди и эльфийские магистры обрушили на троллей огонь, и пламя выжигало раны, которые тролли иначе способны исцелять. Войско Амани дрогнуло и бежало, и их империя так и не оправилась.]=],
		},
		{
			title = "Значение",
			text = [=[В благодарность эльфы {link:quel-thalas}Кель'Талас{/link}а принесли клятву дружбы роду, который основал {link:thoradin}Торадин{/link}. Эта клятва приведет их во {link:second-war}Вторую войну{/link}. Магия, которой обучили людей, разошлась далеко за пределы первой сотни. Она дала начало {link:dalaran}Даларану{/link} и совету {link:kirin-tor}Кирин-Тор{/link} и вновь привлекла внимание {link:burning-legion}Пылающего Легиона{/link}.]=],
		},
	},
})

Translate("ruRU", "first-war", {
	title = "Первая война",
	sections = {
		{
			title = "Обзор",
			text = [=[Первая война была вторжением орочьей {link:horde}Орды{/link} в королевство людей {link:azeroth}Азерот{/link}. Она началась, когда в Черных топях открылся {link:dark-portal}Темный портал{/link}, и завершилась падением {link:stormwind-city}Штормград{/link}а. Это была первая война {link:orcs}орк{/link}ов и людей и начало эпохи, которая с тех пор определяет судьбу мира.]=],
		},
		{
			title = "Истоки",
			text = [=[В своем мире, Дреноре, {link:orcs}орки{/link} были совращены: повелитель демонов {link:kil-jaeden}Кил'джеден{/link} действовал через чернокнижника {link:gul-dan}Гул'дана{/link} и через его {link:shadow-council}Совет Теней{/link}. Их родина умирала. В {link:azeroth}Азерот{/link}е же {link:medivh}Медив{/link}, Хранитель Тирисфаля, давно был одержим духом падшего титана {link:sargeras}Саргерас{/link}а. Действуя заодно с орочьим чернокнижником, Медив помог открыть врата между двумя мирами.]=],
		},
		{
			title = "История",
			text = [=[Первые {link:orcs}орк{/link}и пришли в малом числе и совершали набеги в Черных топях. Затем портал расширился, и {link:horde}Орда{/link} явилась во всей силе; ее вел вождь Чернорук. Король {link:llane-wrynn}Ллейн Ринн{/link} и его защитник {link:anduin-lothar}Андуин Лотар{/link} годами сражались с орками по всему южному королевству. Орда сожгла фермы {link:elwynn-forest}Элвинн{/link}ского леса, чащи Сумеречного леса и {link:northshire-abbey}Аббатство Североземья{/link}. Лотар и молодой маг {link:khadgar}Кадгар{/link} наконец сразили безумного Хранителя в его башне {link:karazhan}Каражан{/link}. Но для королевства было уже поздно. Полуорчиха {link:garona}Гарона{/link} убила короля в его собственной крепости, {link:orgrim-doomhammer}Оргрим Молот Рока{/link} отнял у вождя Чернорука власть над Ордой, и {link:stormwind-city}Штормград{/link} был разграблен.]=],
		},
		{
			title = "Значение",
			text = [=[{link:anduin-lothar}Лотар{/link} увел уцелевших на север, через море, в {link:lordaeron}Лордерон{/link} и взял с собой сына короля, {link:varian-wrynn}Вариан{/link}а. Их предостережения побудили короля {link:terenas-menethil}Теренаса Менетила{/link} собрать {link:alliance}Альянс{/link} и готовиться ко {link:second-war}Второй войне{/link}.]=],
		},
	},
})

Translate("ruRU", "second-war", {
	title = "Вторая война",
	sections = {
		{
			title = "Обзор",
			text = [=[Вторая война шла между {link:horde}Ордой{/link}, которую вел {link:orgrim-doomhammer}Оргрим Молот Рока{/link}, и {link:alliance}Альянсом{/link} {link:lordaeron}Лордерон{/link}а. Орда двинулась на север, чтобы завоевать королевства людей, уцелевшие после {link:first-war}Первой войны{/link}. Она была разбита у Вершины Черной горы.]=],
		},
		{
			title = "История",
			text = [=[Король {link:lordaeron}Лордерона{/link} {link:terenas-menethil}Теренас Менетил{/link} собрал королевства людей в {link:alliance}Альянс{/link}, а его полководцем стал {link:anduin-lothar}Андуин Лотар{/link}. К ним присоединились {link:dwarves}дворф{/link}ы {link:kingdom-of-ironforge}Стальгорна{/link} и {link:gnomes}гном{/link}ы. Так же поступили и эльфы {link:quel-thalas}Кель'Таласа{/link}, связанные старой клятвой, которую принесли роду вождя {link:thoradin}Торадин{/link}а, ибо Лотар был его последним наследником. {link:horde}Орда{/link} пришла в большей силе, чем прежде. Молот Рока привлек на свою сторону {link:ogres}огр{/link}ов и троллей Амани, которых вел Зул'джин. {link:dragonmaw-clan}Клан Драконьей Пасти{/link} поработил красных драконов и летел на них в бой. {link:gul-dan}Гул'дан{/link} поднял рыцарей смерти из трупов павших рыцарей-людей. Орда захватила Каз Модан и сожгла окраины Кель'Таласа. Лорд Перенольд из {link:alterac-mountains}Альтерак{/link}а предал Альянс {link:orcs}орк{/link}ам. Орда дошла до стен самой столицы Лордерона.]=],
		},
		{
			title = "Перелом в войне",
			text = [=[В разгар войны {link:gul-dan}Гул'дан{/link} покинул своего вождя. Он уплыл со своими сторонниками искать Гробницу {link:sargeras}Саргерас{/link}а, и Орде пришлось повернуть назад, чтобы покарать его. {link:alliance}Альянс{/link} воспользовался этим мигом. Он оттеснил Орду на юг, к Вершине Черной горы. Там {link:anduin-lothar}Лотар{/link} пал от руки орочьего вождя. Его помощник {link:turalyon}Туралион{/link} подхватил его знамя и сокрушил Орду в Пылающих степях.]=],
		},
		{
			title = "Значение",
			text = [=[Уцелевших {link:orcs}орк{/link}ов согнали в лагеря для пленных. {link:dark-portal}Темный портал{/link} был разрушен. {link:alliance}Альянс{/link} победил, но победа досталась дорогой ценой. Его королевства вскоре перессорились из-за расходов на лагеря, и {link:gilneas}Гилнеас{/link} со {link:stromgarde-keep}Стромгард{/link}ом покинули Альянс.]=],
		},
	},
})

Translate("ruRU", "third-war", {
	title = "Третья война",
	sections = {
		{
			title = "Обзор",
			text = [=[Третья война была вторым вторжением {link:burning-legion}Пылающего Легиона{/link} в {link:azeroth}Азерот{/link}. Она началась в {link:lordaeron}Лордероне{/link} с чумы нежити и завершилась в {link:kalimdor}Калимдоре{/link}, когда был уничтожен {link:archimonde}Архимонд{/link}. Она стоила людям их величайшего королевства, а ночным эльфам — их бессмертия.]=],
		},
		{
			title = "Истоки",
			text = [=[После Второй войны демон {link:kil-jaeden}Кил'джеден{/link} заточил дух орочьего шамана {link:ner-zhul}Нер'зула{/link} в ледяной темнице в Нордсколе и сделал его Королем-личом. Через некроманта {link:kel-thuzad}Кел'Тузада{/link} и его {link:cult-of-the-damned}Культ Проклятых{/link} Король-лич распространил чуму по деревням {link:lordaeron}Лордерон{/link}а. Ее жертвы восставали нежитью — {link:scourge}Плетью{/link}. В то же время молодой {link:orcs}орк{/link} {link:thrall}Тралл{/link} освободил свой народ из лагерей для пленных и выковал новую {link:horde}Орду{/link}.]=],
		},
		{
			title = "История",
			text = [=[Таинственный пророк предостерегал королей востока и звал их бежать на запад, за море. Король {link:terenas-menethil}Теренас Менетил{/link} не пожелал слушать, но {link:thrall}Тралл{/link} и {link:jaina-proudmoore}Джайна Праудмур{/link} вняли зову. Этим пророком был {link:medivh}Медив{/link}, вернувшийся из мертвых. В {link:lordaeron}Лордерон{/link}е принц {link:arthas-menethil}Артас Менетил{/link} шел по следу чумы к ее истоку. После {link:culling-of-stratholme}Очищения Стратхольма{/link} он отплыл в Нордскол и взял проклятый клинок, Ледяную Скорбь. Он вернулся рыцарем смерти и принес с собой {link:fall-of-lordaeron}падение Лордерона{/link}. {link:scourge}Плеть{/link} воскресила некроманта {link:kel-thuzad}Кел'Тузад{/link}а в Солнечном Колодце {link:quel-thalas}Кель'Талас{/link}а, а {link:archimonde}Архимонд{/link} вошел в мир в {link:dalaran}Даларан{/link}е и разрушил его. Затем Легион последовал за Ордой и людьми в {link:kalimdor}Калимдор{/link}. Там ночные эльфы поднялись после своего бдения.]=],
		},
		{
			title = "Значение",
			text = [=[{link:orcs}Орки{/link}, люди и ночные эльфы наконец объединились ради общего дела. В {link:battle-of-mount-hyjal}битве у горы Хиджал{/link} они уничтожили {link:archimonde}Архимонд{/link}а. Из этой войны родились земли новой Орды в {link:kalimdor}Калимдор{/link}е, {link:theramore-isle}город Терамор{/link} и {link:forsaken}Отрекшиеся{/link}. Ее раны открыты до сих пор.]=],
		},
	},
})

Translate("ruRU", "battle-of-mount-hyjal", {
	title = "Битва у горы Хиджал",
	aliases = { "Битва за Хиджал" },
	sections = {
		{
			title = "Обзор",
			text = [=[Битва у горы Хиджал была последней битвой {link:third-war}Третьей войны{/link}. На склонах священной горы {link:orcs}орк{/link}и, люди и ночные эльфы встали вместе против {link:burning-legion}Пылающего Легиона{/link}. Повелитель демонов {link:archimonde}Архимонд{/link} был уничтожен у корней древа {link:nordrassil}Нордрассил{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[Легион пришел в {link:kalimdor}Калимдор{/link} ради Древа Жизни. {link:archimonde}Архимонд{/link} намеревался вытянуть силу второго Источника Вечности, который лежал под его корнями, и тем самым поглотить мир. Перед ним шла {link:scourge}Плеть{/link}. {link:night-elves}Ночные эльфы{/link}, которых вели {link:tyrande-whisperwind}Тиранда Шелест Ветра{/link} и {link:malfurion-stormrage}Малфурион Ярость Бури{/link}, не могли выстоять одни. {link:medivh}Медив{/link} свел их предводителей с двумя другими: это были {link:thrall}Тралл{/link}, вождь Орды, и {link:jaina-proudmoore}Джайна Праудмур{/link}, глава людей. Он сказал им, что выжить они смогут только вместе.]=],
		},
		{
			title = "История",
			text = [=[План придумал {link:malfurion-stormrage}Малфурион{/link}. Сначала на нижних склонах заняли оборону люди, затем выше — {link:orcs}орк{/link}и, и каждый держался сколько мог, прежде чем отступить. Пока они сражались, Малфурион готовил ловушку на вершине. {link:archimonde}Архимонд{/link} прорвал одну линию за другой и наконец добрался до древа. Когда он стал взбираться на {link:nordrassil}Нордрассил{/link}, Малфурион затрубил в Рог Кенария. Духи предков ночных эльфов, собравшиеся бесчисленными огоньками, роем налетели на демона. Их сила и сила Древа Жизни высвободились в едином взрыве. Архимонд был уничтожен.]=],
		},
		{
			title = "Значение",
			text = [=[Победа спасла мир, но далась великой ценой. {link:nordrassil}Нордрассил{/link} отдал свою силу, и ночные эльфы лишились бессмертия, которое он им даровал. Древо было опалено, но не убито. Эта битва также выковала недолгий мир между {link:alliance}Альянс{/link}ом и Ордой.]=],
		},
	},
})

Translate("ruRU", "culling-of-stratholme", {
	title = "Очищение Стратхольма",
	sections = {
		{
			title = "Обзор",
			text = [=[Очищение Стратхольма — истребление жителей Стратхольма солдатами, которых вел принц {link:arthas-menethil}Артас Менетил{/link}. Оно случилось в {link:third-war}Третью войну{/link}, когда чума нежити достигла города. С него началось падение принца.]=],
		},
		{
			title = "Истоки",
			text = [=[{link:arthas-menethil}Артас{/link} шел по следу чумы через весь {link:lordaeron}Лордерон{/link}, и с ним были волшебница {link:jaina-proudmoore}Джайна Праудмур{/link} и его наставник {link:uther-the-lightbringer}Утер Светоносный{/link}. Он узнал, что {link:cult-of-the-damned}Культ Проклятых{/link} заразил зерно, которое развозили из амбаров {link:ruins-of-andorhal}Андорал{/link}а. В Стратхольме он обнаружил, что зараженное зерно уже роздано. Каждый, кто его ел, вскоре должен был умереть и восстать одним из воинов {link:scourge}Плети{/link}.]=],
		},
		{
			title = "История",
			text = [=[{link:arthas-menethil}Артас{/link} приказал очистить город, прежде чем его жители обратятся. {link:uther-the-lightbringer}Утер{/link} отказался участвовать в этом, и принц лишил его командования за измену. {link:jaina-proudmoore}Джайна{/link} не пожелала на это смотреть и покинула его. Принц повел оставшихся верными солдат в Стратхольм и предал его жителей мечу, дом за домом. Там, куда солдаты еще не дошли, горожане уже обращались. В городе ждал повелитель ужаса Мал'Ганис. Он насмехался над принцем и вызвал его последовать за ним в Нордскол. Артас поклялся настичь его.]=],
		},
		{
			title = "Значение",
			text = [=[Очищение разорвало узы между принцем и теми, кто его любил. Оно отправило его на север, к Ледяной Скорби и к {link:fall-of-lordaeron}падению Лордерона{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[Стратхольм лежит в руинах в {link:eastern-plaguelands}Восточных Чумных землях{/link}. {link:scourge}Плеть{/link} удерживает большую часть города. {link:scarlet-crusade}Алый орден{/link} цепляется за остальное и все еще сражается с мертвецами, которых не смог спасти меч принца.]=],
		},
	},
})

Translate("ruRU", "fall-of-lordaeron", {
	title = "Падение Лордерона",
	sections = {
		{
			title = "Обзор",
			text = [=[Падение Лордерона — гибель величайшего королевства людей от рук {link:scourge}Плети{/link}. Оно случилось в {link:third-war}Третью войну{/link}, когда принц {link:arthas-menethil}Артас Менетил{/link} вернулся из Нордскола слугой Короля-лича. Из всех королевств, что вели {link:alliance}Альянс{/link}, ни одно не пало так низко и так быстро.]=],
		},
		{
			title = "История",
			text = [=[В Нордсколе {link:arthas-menethil}Артас{/link} взял рунический клинок, Ледяную Скорбь, и сразил повелителя ужаса Мал'Ганиса. Клинок отнял у него душу. Он отплыл домой, и жители столицы встретили его как героя. Он вошел в тронный зал и убил своего отца, короля {link:terenas-menethil}Теренаса Менетила{/link}. Следом за ним королевство захлестнула {link:scourge}Плеть{/link}. Артас убил паладина {link:uther-the-lightbringer}Утера Светоносного{/link} и забрал урну с прахом своего отца, чтобы везти в ней останки некроманта {link:kel-thuzad}Кел'Тузада{/link}. Он вторгся в {link:quel-thalas}Кель'Талас{/link}, сразил его защитников, которых вела {link:sylvanas-windrunner}Сильвана Ветрокрылая{/link}, и воскресил некроманта в водах Солнечного Колодца. Вскоре после этого Плеть помогла демону {link:archimonde}Архимонду{/link} войти в мир в {link:dalaran}Даларане{/link}.]=],
		},
		{
			title = "После падения",
			text = [=[Когда {link:archimonde}Архимонд{/link} был уничтожен, повелители ужаса вознамерились сами править разоренным королевством. {link:arthas-menethil}Артас{/link} обратился против них, прежде чем ответил на зов своего господина и ушел на север. {link:sylvanas-windrunner}Сильвана{/link}, теперь уже нежить, вырвалась из-под воли Короля-лича. Она и ее {link:forsaken}Отрекшиеся{/link} низвергли повелителей ужаса и заняли руины столицы.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:lordaeron}Лордерон{/link}а больше нет. Его сердце — Чумные земли, которые удерживает {link:scourge}Плеть{/link}. {link:scarlet-crusade}Алый орден{/link} сражается с мертвецами в {link:tirisfal-glades}Тирисфальских лесах{/link} и за их пределами. Под разрушенным тронным залом {link:forsaken}Отрекшиеся{/link} построили {link:undercity}Подгород{/link}.]=],
		},
	},
})

Translate("ruRU", "dark-portal", {
	title = "Темный портал",
	sections = {
		{
			title = "Обзор",
			text = [=[Темный портал — великие врата между {link:azeroth}Азерот{/link}ом и родиной {link:orcs}орк{/link}ов, Дренором. Он стоит в {link:blasted-lands}Выжженных землях{/link}, которые некогда были болотами Черных топей. Через него пришла {link:horde}Орда{/link}, и с него началась {link:first-war}Первая война{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[Портал открыли со стороны Дренора чернокнижник {link:gul-dan}Гул'дан{/link} и его {link:shadow-council}Совет Теней{/link}, а в {link:azeroth}Азерот{/link}е им помог {link:medivh}Медив{/link}. Он был Хранителем Тирисфаля, но его разумом давно владел {link:sargeras}Саргерас{/link}, повелитель {link:burning-legion}Пылающего Легиона{/link}. Поначалу разлом был узок, и через него прошли лишь немногие разведчики. Потом его расширили, и вся {link:horde}Орда{/link} перешла в болота.]=],
		},
		{
			title = "История",
			text = [=[{link:horde}Орда{/link} возвела вокруг портала {link:ogres}огр{/link}омную крепость, и он стал дорогой для ее подкреплений. Когда {link:second-war}Вторая война{/link} была проиграна, {link:alliance}Альянс{/link} разрушил Темный портал. Несколько лет спустя шаман {link:ner-zhul}Нер'зул{/link} открыл его снова и провел через него новую Орду, чтобы похитить артефакты силы. Альянс отправил экспедицию на ту сторону, в Дренор, чтобы покончить с угрозой у самого ее источника. Нер'зул разорвал ткань мира и открыл разломы в другие миры, и портал был разрушен снова. Экспедиция не вернулась. Никто в {link:azeroth}Азерот{/link}е не знает, что с ней сталось.]=],
		},
		{
			title = "Наши дни",
			text = [=[Темный портал стоит, темный и безмолвный, на южном краю Выжженных земель. За ним следят маги и солдаты Крепости Стражей Пустоты. Демоны все еще бродят по бесплодной земле вокруг него.]=],
		},
	},
})

Translate("ruRU", "well-of-eternity", {
	title = "Источник Вечности",
	sections = {
		{
			title = "Обзор",
			text = [=[Источник Вечности был {link:ogres}огр{/link}омным озером тайной силы в сердце древнего мира. На его берегах поднялась империя Калдореи. Его уничтожение завершило {link:war-of-the-ancients}Войну древних{/link} и вызвало {link:great-sundering}Великий Раскол{/link}.]=],
		},
		{
			title = "Природа",
			text = [=[Древнейшие летописи говорят, что Источник заполнил рану в земле, которую оставила война титанов с Древними богами. Его воды были черны и глубоки и хранили первозданную силу самого мира. {link:trolls}Тролли{/link}, которые поселились рядом с ним, менялись на протяжении многих поколений и стали {link:night-elves}ночными эльфами{/link}. Они научились повелевать его силой, и их власть над {link:arcane-magic}тайной магией{/link} сделала их империю чудом света.]=],
		},
		{
			title = "История",
			text = [=[Королева ночных эльфов {link:queen-azshara}Азшара{/link} построила свой дворец на берегах Источника, и ее высокорожденные черпали из него все глубже. Их магия привлекла {link:burning-legion}Пылающий Легион{/link}. Высокорожденные попытались открыть врата в самом Источнике, чтобы через них прошел {link:sargeras}Саргерас{/link}. Когда врата были разрушены, Источник рухнул, и континент был разорван на части. Там, где он был, ныне бушует Водоворот.]=],
		},
		{
			title = "Его наследие",
			text = [=[Кое-что от Источника уцелело. {link:illidan-stormrage}Иллидан Ярость Бури{/link} сохранил сосуды с его водой и вылил их в озеро на горе Хиджал, создав второй Источник. Там Аспекты посадили древо {link:nordrassil}Нордрассил{/link}. Изгнанные высокорожденные унесли еще один сосуд на восток. С его помощью они создали Солнечный Колодец, источник силы {link:quel-thalas}Кель'Таласа{/link}. В {link:third-war}Третью войну{/link} {link:archimonde}Архимонд{/link} пришел в {link:kalimdor}Калимдор{/link}, чтобы поглотить силу второго Источника, и потерпел неудачу.]=],
		},
	},
})

Translate("ruRU", "nordrassil", {
	title = "Нордрассил",
	sections = {
		{
			title = "Обзор",
			text = [=[Нордрассил — Древо Жизни, которое поднимается с вершины горы Хиджал в {link:kalimdor}Калимдоре{/link}. Десять тысяч лет оно охраняло второй {link:well-of-eternity}Источник Вечности{/link} и давало {link:night-elves}ночным эльфам{/link} бессмертие. Оно было средоточием {link:battle-of-mount-hyjal}битвы у горы Хиджал{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[После {link:great-sundering}Великого Раскола{/link} уцелевшие ночные эльфы обнаружили, что {link:illidan-stormrage}Иллидан Ярость Бури{/link} создал новый Источник на вершине горы Хиджал. К ним явились драконы-Аспекты. {link:alexstrasza}Алекстраза{/link} опустила в воды нового Источника священное семя, и из него поднялось {link:ogres}огр{/link}омное древо; его корни пили из Источника и запечатывали его. Ноздорму благословил древо, чтобы ночные эльфы жили, пока оно стоит. Изера связала его с {link:emerald-dream}Изумрудным Сном{/link}, чтобы друиды могли через него странствовать по Сну.]=],
		},
		{
			title = "История",
			text = [=[Под его ветвями ночные эльфы несли свое долгое бдение. В его тени спали друиды, главой которых был {link:malfurion-stormrage}Малфурион Ярость Бури{/link}, и их духи блуждали по Сну. В {link:third-war}Третью войну{/link} {link:archimonde}Архимонд{/link} двинулся к древу, чтобы осушить Источник под ним. Когда он взбирался по стволу, Малфурион призвал духов предков, и сила древа была истрачена на уничтожение демона.]=],
		},
		{
			title = "Наши дни",
			text = [=[Нордрассил все еще стоит, израненный и ослабевший. {link:night-elves}Ночные эльфы{/link} больше не бессмертны. Они посадили новое древо, {link:teldrassil}Тельдрассил{/link}, у северного побережья, но оно было выращено без благословения Аспектов. Многие из старых друидов сомневаются, следовало ли вообще его растить.]=],
		},
	},
})

Translate("ruRU", "holy-light", {
	title = "Свет",
	sections = {
		{
			title = "Обзор",
			text = [=[Свет — сила веры и добродетели, которая отвечает преданным. Его жрецы исцеляют раны и врачуют души. Его паладины несут его в бой как щит и как оружие против нежити и демонов. Большинство людей {link:eastern-kingdoms}Восточных королевств{/link} воспитаны в его вере, и многие {link:dwarves}дворфы{/link} ныне разделяют ее.]=],
		},
		{
			title = "Природа",
			text = [=[Верующие не учат, что Свет — это бог. Они учат, что он пребывает во всех, кто стремится к добродетели, и что он крепнет через сострадание, мужество и самопожертвование. Его нельзя украсть или обратить к жестокости. Те, кто пытается владеть им без веры, обнаруживают, что он не отвечает им.]=],
		},
		{
			title = "История",
			text = [=[Вера в Свет имеет глубокие корни среди людей и восходит ко временам {link:arathor}Аратора{/link}. В королевстве {link:stormwind-city}Штормград{/link} ее хранили в Аббатстве Североземья и в Соборе Света. После {link:first-war}Первой войны{/link} архиепископ {link:alonsus-faol}Алонсий Фаол{/link} увидел, что одна лишь вера не спасла юг. Он соединил служителей Света с лучшими рыцарями {link:lordaeron}Лордерон{/link}а и основал орден Серебряной Длани — первых паладинов. Первым из них был {link:uther-the-lightbringer}Утер Светоносный{/link}. Паладины с честью сражались всю {link:second-war}Вторую войну{/link}. В {link:third-war}Третью войну{/link} орден был разорван на части. Принц {link:arthas-menethil}Артас Менетил{/link} был одним из них.]=],
		},
		{
			title = "Наши дни",
			text = [=[Свет по-прежнему остается сердцем веры {link:stormwind-city}Штормград{/link}а, и его жрецы служат в каждом городе. В {link:lordaeron}Лордероне{/link} он стал боевым кличем. {link:scarlet-crusade}Алый орден{/link} именем Света сжигает всех, кого подозревает в чуме. {link:argent-dawn}Серебряный Рассвет{/link} сражается с теми же мертвецами более твердой рукой.]=],
		},
	},
})

Translate("ruRU", "arcane-magic", {
	title = "Тайная магия",
	sections = {
		{
			title = "Обзор",
			text = [=[Тайная магия — магия разума и узоров мира. Ее мастера искривляют пространство и время, призывают огонь и лед и видят то, чего не видят другие. Это древнейшая из изучаемых магий {link:azeroth}Азерот{/link}а и самая опасная для тех, кто любит ее слишком сильно.]=],
		},
		{
			title = "Природа",
			text = [=[Тайной силе могут научиться те, у кого есть талант и дисциплина, но она ничего не дает даром. Те, кто владеет ею, начинают жаждать ее. Она также взывает к демонам {link:burning-legion}Пылающего Легиона{/link}, которые алчут миров, богатых магией. Каждая великая эпоха тайной силы в {link:azeroth}Азерот{/link}е привлекала взор Легиона.]=],
		},
		{
			title = "История",
			text = [=[{link:night-elves}Ночные эльфы{/link} первыми овладели тайной магией у {link:well-of-eternity}Источника Вечности{/link}, и их высокорожденные с ее помощью вызвали {link:war-of-the-ancients}Войну древних{/link}. После {link:great-sundering}Великого Раскола{/link} ночные эльфы объявили ее вне закона. Высокорожденные, которые не пожелали от нее отказаться, были изгнаны. Они основали на востоке {link:quel-thalas}Кель'Талас{/link} и стали {link:high-elves}высшими эльфами{/link}. В {link:troll-wars}Войнах с троллями{/link} они обучили магии сто человек из {link:arathor}Аратора{/link}. Это искусство разошлось по землям людей. Маги Аратора воздвигли город {link:dalaran}Даларан{/link}, а его правящий совет, {link:kirin-tor}Кирин-Тор{/link}, надзирал за тем, как применяют магию. Когда в землях людей начали появляться демоны, эльфы и маги основали тайный {link:shadow-council}Совет{/link} Тирисфаля. Они избирали Хранителя, чтобы тот в одиночку сражался с Легионом. Последними Хранителями были {link:aegwynn}Эгвин{/link} и ее сын {link:medivh}Медив{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:dalaran}Даларан{/link} разрушил {link:archimonde}Архимонд{/link} в {link:third-war}Третью войну{/link}. Ныне его маги отстраивают город за мерцающей фиолетовой преградой в предгорьях {link:alterac-mountains}Альтерак{/link}а. Маги по-прежнему учатся в {link:stormwind-city}Штормград{/link}е, {link:ironforge}Стальгорн{/link}е и {link:theramore-isle}Терамор{/link}е. Среди ночных эльфов старый закон против тайной магии остается в силе.]=],
		},
	},
})

Translate("ruRU", "fel-magic", {
	title = "Магия Скверны",
	sections = {
		{
			title = "Обзор",
			text = [=[Магия Скверны — магия {link:burning-legion}Пылающего Легиона{/link}. Она черпает силу в разрушении и в краже жизни. Она горит болезненным зеленым огнем и отравляет землю и души тех, кто ею пользуется. Чернокнижники по-прежнему торгуются с ней, зная цену.]=],
		},
		{
			title = "Природа",
			text = [=[Сила Скверны быстра и могуча и требует немного учения. Взамен она требует, чтобы было что-то поглощено: жизнь, душа, здоровье земли. Те, кто пользуется ею, медленно меняются телом и сердцем. Места, где ее применяли часто, чахнут и гниют.]=],
		},
		{
			title = "История",
			text = [=[Магия Скверны впервые пришла в {link:azeroth}Азерот{/link} вместе с Легионом в {link:war-of-the-ancients}Войну древних{/link}. Многие высокорожденные, служившие демонам, были искажены и стали {link:satyrs}сатирами{/link}. Десять тысяч лет спустя она пришла снова, через {link:orcs}орков{/link}. На Дреноре повелитель демонов {link:kil-jaeden}Кил'джеден{/link} открыл ее тайны чернокнижнику {link:gul-dan}Гул'дану{/link} и его собратьям. Вожди орков испили кровь демона {link:mannoroth}Маннорот{/link}а, и она наполнила их ужасной яростью. Земля Дренора умерла под их магией. Орки пронесли проклятие через {link:dark-portal}Темный портал{/link} в {link:first-war}Первую войну{/link} и во {link:second-war}Вторую войну{/link}. В {link:third-war}Третью войну{/link} {link:grom-hellscream}Гром Адский Крик{/link} сразил демона Маннорота и ценой собственной жизни освободил свой народ от демонической крови. {link:illidan-stormrage}Иллидан Ярость Бури{/link} поглотил {link:skull-of-gul-dan}Череп Гул'дана{/link} и обрел силу демона.]=],
		},
		{
			title = "Наши дни",
			text = [=[Леса {link:felwood}Оскверненного леса{/link} все еще несут на себе порчу Легиона. Чернокнижники {link:burning-blade}Пылающего Клинка{/link} служат демонам в тенях {link:orgrimmar}Оргриммар{/link}а и {link:durotar}Дуротар{/link}а. {link:satyrs}Сатиры{/link} рыщут в Ясеневом лесу. Чернокнижники {link:alliance}Альянс{/link}а и Орды по-прежнему изучают это искусство. Они настаивают, что это они его хозяева.]=],
		},
	},
})

Translate("ruRU", "emerald-dream", {
	title = "Изумрудный Сон",
	sections = {
		{
			title = "Обзор",
			text = [=[Изумрудный Сон — {link:ogres}огр{/link}омное царство духов, зеркало мира. Он показывает {link:azeroth}Азерот{/link} таким, каким тот мог бы быть: диким и не тронутым руками смертных. Его хранительница — Изера, Аспект зеленых драконов. Друиды {link:night-elves}ночных эльфов{/link} странствуют по нему духом, пока их тела спят.]=],
		},
		{
			title = "Природа",
			text = [=[Летописи утверждают, что титаны создали Сон как живой образ своего замысла о мире. Это царство роста и сновидений. Зеленые драконы охраняют его врата, а в нем обитают духи дикой природы. Время и расстояние там не подчиняются законам мира яви.]=],
		},
		{
			title = "История",
			text = [=[Полубог {link:cenarius}Кенарий{/link} обучил друидизму ночного эльфа {link:malfurion-stormrage}Малфуриона Ярость Бури{/link}, и через это учение Малфурион научился входить в Сон. После {link:war-of-the-ancients}Войны древних{/link} Изера связала {link:nordrassil}Нордрассил{/link} со Сном. Тысячи лет друиды {link:cenarion-circle}Круга Кенария{/link} спали в сокрытых подземных обителях, и их духи блуждали по Сну, пока {link:sentinels}Часовые{/link} стерегли их тела. Их разбудили, чтобы сражаться в {link:third-war}Третьей войне{/link}. После победы друиды вернулись к своему труду.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:malfurion-stormrage}Малфурион{/link} снова ушел в Сон и не вернулся. В его отсутствие друидов ведет {link:fandral-staghelm}Фэндрал Олений Шлем{/link}. В Сне что-то неладно. В мире яви видят зеленых драконов, и некоторые из них уже не те, кем были прежде. Друиды Лунной поляны говорят о тьме, которая расползается по Сну и которой никто пока не может дать имени.]=],
		},
	},
})

Translate("ruRU", "elements", {
	title = "Стихии",
	sections = {
		{
			title = "Обзор",
			text = [=[Стихии — живые силы земли, огня, воды и воздуха. В первозданном виде они дики и разрушительны. В равновесии они поддерживают мир. Шаманы {link:orcs}орков{/link}, {link:tauren}тауренов{/link} и {link:trolls}троллей{/link} говорят с духами стихий и просят их о помощи.]=],
		},
		{
			title = "Природа",
			text = [=[Стихиями правят четыре великих повелителя. {link:ragnar-thunderbrew}Рагнар{/link}ос — повелитель огня. Теразан — мать камня. {link:al-akir}Ал'Акир{/link} — повелитель ветров, и его царство — {link:skywall}Небесная Высь{/link}. Нептулон — повелитель приливов. Их слуги дики и враждебны жизни смертных. С меньшими духами, однако, можно договориться. Шаман не повелевает ими. Шаман просит, а духи решают, отвечать ли.]=],
		},
		{
			title = "История",
			text = [=[В первую эпоху мира повелители стихий сражались за Древних богов. Титаны победили их и заточили в царстве, отделенном от мира. На Дреноре {link:orcs}орк{/link}и были народом шаманов. Когда {link:gul-dan}Гул'дан{/link} обратил их к магии демонов, духи покинули их. Гораздо позже, в Каз Модане, тан клана Черного Железа {link:ruins-of-thaurissan}Тауриссан{/link} призвал в мир повелителя огня. Этот призыв убил тана и воздвиг Черную гору. С тех пор {link:ragnar-thunderbrew}Рагнар{/link}ос обитает под ней. После {link:second-war}Второй войны{/link} старый шаман {link:drek-thar}Дрек'Тар{/link} научил путям духов юного орка {link:thrall}Тралла{/link}. Стихии ответили новой Орде так, как не отвечали старой.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:ragnar-thunderbrew}Рагнар{/link}ос правит {link:dwarves}дворф{/link}ами Черного Железа из расплавленных глубин Черной горы. {link:twilight-s-hammer}Сумеречный Молот{/link} стремится пробудить стихии ради собственных целей. Шаманы Орды хранят старое равновесие, как хранили его их предки до прихода демонов.]=],
		},
	},
})
